    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #4f545c;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

